// Parse and validate guild matching request
const body = $input.item.json.body || $input.item.json;

const storyId = body.story_id;
const expertiseArea = body.expertise_area || '';
const minProficiency = body.min_proficiency || 3;
const maxExperts = body.max_experts || 5;
const action = body.action || 'match';

if (!storyId && action !== 'search') {
  throw new Error('story_id is required for guild matching');
}

let chatInput = '';

switch (action) {
  case 'match':
    chatInput = `Find the best expert match for story ${storyId}. ` +
      (expertiseArea ? `Focus on expertise area: ${expertiseArea}. ` : '') +
      `Minimum proficiency: ${minProficiency}. Return up to ${maxExperts} candidates.`;
    break;
  case 'assign':
    if (!body.expert_id) throw new Error('expert_id is required for assign action');
    chatInput = `Assign expert ${body.expert_id} to story ${storyId}. ` +
      (body.role ? `Role: ${body.role}. ` : '') +
      (body.reason ? `Reason: ${body.reason}` : '');
    break;
  case 'search':
    chatInput = `Search for experts with expertise in: ${expertiseArea || body.query}. ` +
      `Minimum proficiency: ${minProficiency}. Limit: ${maxExperts}.`;
    break;
  case 'evaluate':
    chatInput = `Evaluate current expert assignments for story ${storyId}. ` +
      `Check if expertise coverage is adequate and suggest improvements.`;
    break;
  default:
    chatInput = `Guild matching task: ${JSON.stringify(body)}`;
}

return {
  json: {
    chatInput,
    session_id: body.session_id || `guild-${storyId || 'search'}-${Date.now()}`,
    context: {
      story_id: storyId,
      action,
      expertise_area: expertiseArea,
      min_proficiency: minProficiency,
      max_experts: maxExperts,
      source: body.source || 'webhook'
    }
  }
};

// Format guild match response
const agentOutput = $input.item.json;
const context = $('Validate Input').item.json.context;

return {
  json: {
    success: true,
    agent: 'guild_match',
    response: agentOutput.output || agentOutput.text || agentOutput,
    context: {
      story_id: context.story_id,
      action: context.action,
      expertise_area: context.expertise_area
    },
    timestamp: new Date().toISOString()
  }
};

