// MCP Tool: get_story_context
// Retrieves story context for guild matching decisions
const storyId = $input.item.json.story_id || $input.item.json.p_story_id;
if (!storyId) return { error: 'story_id is required' };

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.AISHA_POSTGREST_URL}/rest/v1/rpc/get_story_context`,
  headers: {
    'apikey': $env.AISHA_POSTGREST_SERVICE_KEY,
    'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
    'Content-Type': 'application/json'
  },
  body: { p_story_id: storyId }
});
return resp;

// MCP Tool: match_experts
// Finds experts matching required expertise area and proficiency
const area = $input.item.json.expertise_area || $input.item.json.p_expertise_area || '';
const profMin = Number($input.item.json.proficiency_min || $input.item.json.p_proficiency_min || 3);
const limit = Number($input.item.json.limit || $input.item.json.p_limit || 5);

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.AISHA_POSTGREST_URL}/rest/v1/rpc/match_experts`,
  headers: {
    'apikey': $env.AISHA_POSTGREST_SERVICE_KEY,
    'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
    'Content-Type': 'application/json'
  },
  body: {
    p_expertise_area: area,
    p_proficiency_min: profMin,
    p_limit: limit
  }
});
return resp;

// MCP Tool: assign_expert_to_story
// Assigns an expert to a story with a role
const storyId = $input.item.json.story_id || $input.item.json.p_story_id;
const expertId = $input.item.json.expert_id || $input.item.json.p_expert_id;
const role = $input.item.json.role || $input.item.json.p_role || 'specialist';

if (!storyId || !expertId) return { error: 'story_id and expert_id are required' };

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.AISHA_POSTGREST_URL}/rest/v1/rpc/assign_expert_to_story`,
  headers: {
    'apikey': $env.AISHA_POSTGREST_SERVICE_KEY,
    'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
    'Content-Type': 'application/json'
  },
  body: {
    p_story_id: storyId,
    p_expert_id: expertId,
    p_role: role
  }
});
return resp;

// MCP Tool: search_knowledge
// Searches knowledge base for expertise context
const query = $input.item.json.query || $input.item.json.p_query || '';
if (!query) return { error: 'query is required' };

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.AISHA_POSTGREST_URL}/rest/v1/rpc/mcp_search_knowledge_v2`,
  headers: {
    'apikey': $env.AISHA_POSTGREST_SERVICE_KEY,
    'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
    'Content-Type': 'application/json'
  },
  body: {
    p_query: query,
    p_limit: 5,
    p_tags: []
  }
});
return resp;
